322	```ts
323	// redact.ts
324	const RULES: [string, RegExp][] = [
325	  ['private_key', /-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]*?-----END [A-Z ]*PRIVATE KEY-----/g],
326	  ['jwt', /\beyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}/g],
327	  ['bearer', /(Bearer\s+)[A-Za-z0-9._~+/-]{20,}/g],
328	  ['provider_key', /\b(?:sk|pk|rk)-[A-Za-z0-9_-]{16,}/g],
329	  ['github_token', /\bgh[pousr]_[A-Za-z0-9]{20,}/g],
330	  ['aws_key_id', /\bAKIA[0-9A-Z]{16}\b/g],
331	  ['google_key', /\bAIza[0-9A-Za-z_-]{30,}/g],
332	  ['slack_token', /\bxox[baprs]-[A-Za-z0-9-]{10,}/g],
333	  ['assignment', /\b([A-Z0-9_]*(?:KEY|TOKEN|SECRET|PASSWORD|PASSWD)[A-Z0-9_]*\s*[=:]\s*["']?)([^\s"'\[]{8,})/g],
334	];
335	export function redact(input: string): { text: string; hits: number } {
336	  let hits = 0; let text = input;
337	  for (const [kind, re] of RULES) {
338	    text = text.replace(re, (...m) => {
339	      hits += 1;
340	      const keep = kind === 'bearer' || kind === 'assignment' ? (m[1] as string) : '';
341	      return `${keep}[REDACTED:${kind}]`;
342	    });
343	  }
344	  return { text, hits };
345	}
346	```
347	The `assignment` rule skips values that already start with `[` so an earlier replacement is not counted twice.
