349	```ts
350	// env.ts
351	import { readFileSync, existsSync } from 'node:fs';
352	import { resolve } from 'node:path';
353	export interface Env {
354	  neatlogsApiKey: string | null; neatlogsEndpoint: string;
355	  gatewayKey: string | null; gatewayBaseUrl: string;
356	  veniceKey: string | null; geminiKeys: string[]; dataDir: string;
357	}
358	export function loadEnv(cwd = process.cwd()): Env {
359	  const file = resolve(cwd, '.env');
360	  if (existsSync(file)) for (const line of readFileSync(file, 'utf8').split('\n')) {
361	    const m = /^([A-Z0-9_]+)=(.*)$/.exec(line.trim());
362	    if (m && process.env[m[1]!] === undefined) process.env[m[1]!] = m[2]!.replace(/^["']|["']$/g, '');
363	  }
364	  const e = process.env;
365	  return {
366	    neatlogsApiKey: e.NEATLOGS_API_KEY || null,
367	    neatlogsEndpoint: e.NEATLOGS_ENDPOINT || 'https://ingest.neatlogs.com',
368	    gatewayKey: e.LITELLM_API_KEY || null,
369	    gatewayBaseUrl: e.LITELLM_BASE_URL || 'https://litellm.vision.aivar.app/v1',
370	    veniceKey: e.VENICE_API_KEY || null,
371	    geminiKeys: (e.GEMINI_API_KEYS || '').split(',').map((s) => s.trim()).filter(Boolean),
372	    dataDir: resolve(cwd, e.DAILIES_DATA_DIR || '.dailies'),
373	  };
374	}
