                  content: [
                    { type: 'tool_use', id: 't1', name: 'Bash', input: { command: 'pnpm test' }, result: { output: '2 passed', status: 'success' } },
                    { type: 'text', text: 'All tests pass.' },
                  ],
                },
              ],
