          ts: '2026-10-10T07:00:05Z',
          content: [
            { type: 'tool_use', id: 't1', name: 'Bash', input: { command: 'pnpm test' }, result: { output: '2 failed', status: 'error' } },
            { type: 'text', text: 'All tests pass.' },
          ],
