import { entryId, redact, type Entry, type EntryKind } from '@dailies/core';

const MAX_ENTRIES = 5000;
const TOOL_OUTPUT_LIMIT = 8000;
const TOOL_OUTPUT_HEAD = 3000;
const TOOL_OUTPUT_TAIL = 5000;
const TOOL_INPUT_LIMIT = 4000;
// eslint-disable-next-line no-control-regex
const ANSI_RE = /\u001b\[[0-9;]*[A-Za-z]/g;

function stripAnsi(text: string): string {
  return text.replace(ANSI_RE, '');
}

function truncateToolOutput(text: string): string {
  const stripped = stripAnsi(text);
  if (stripped.length <= TOOL_OUTPUT_LIMIT) return stripped;
  return `${stripped.slice(0, TOOL_OUTPUT_HEAD)}\n…[truncated]…\n${stripped.slice(-TOOL_OUTPUT_TAIL)}`;
}

interface ToolUseBlock {
  type: 'tool_use';
  id: string;
  name: string;
  input?: Record<string, unknown>;
  result?: { output?: string; status?: string };
}

interface TextBlock {
  type?: string;
  id?: string;
  text?: string;
}

type Block = ToolUseBlock | TextBlock;

interface TranscriptLine {
  type?: string;
  ts?: string;
  content?: Block[];
}

/** Parses one session's `transcript.jsonl` into typed entries. A malformed line is skipped, not fatal. */
export function parseTranscript(sessionId: string, jsonl: string): { entries: Entry[]; redactions: number } {
  const entries: Entry[] = [];
  let redactions = 0;
  let index = 0;

  const pushEntry = (partial: Omit<Entry, 'id' | 'sessionId' | 'index'>) => {
    if (entries.length >= MAX_ENTRIES) return;
    entries.push({ id: entryId(sessionId, index), sessionId, index, ...partial });
    index += 1;
  };

  for (const rawLine of jsonl.split('\n')) {
    if (entries.length >= MAX_ENTRIES) break;
    const line = rawLine.trim();
    if (!line) continue;

    let msg: TranscriptLine;
    try {
      msg = JSON.parse(line);
    } catch {
      continue;
    }
    if (!msg || typeof msg !== 'object') continue;

    const ts: string | null = typeof msg.ts === 'string' ? msg.ts : null;
    const content = Array.isArray(msg.content) ? msg.content : [];

    if (msg.type === 'user') {
      for (const block of content as TextBlock[]) {
        if (!block || block.type === 'image') continue;
        if (typeof block.text !== 'string') continue;
        const r = redact(block.text);
        redactions += r.hits;
        pushEntry({ ts, kind: 'user' as EntryKind, text: r.text });
      }
    } else if (msg.type === 'assistant') {
      for (const block of content) {
        if (!block || (block as TextBlock).type === 'image') continue;

        if ((block as ToolUseBlock).type === 'tool_use') {
          const toolUse = block as ToolUseBlock;
          const input = toolUse.input ?? {};
          const command = typeof input.command === 'string' ? input.command : undefined;
          const filePath = typeof input.file_path === 'string' ? input.file_path : undefined;

          const redactedCommand = command !== undefined ? redact(command) : null;
          if (redactedCommand) redactions += redactedCommand.hits;

          const inputJson = JSON.stringify(input).slice(0, TOOL_INPUT_LIMIT);
          const redactedInput = redact(inputJson);
          redactions += redactedInput.hits;

          pushEntry({
            ts,
            kind: 'tool_call' as EntryKind,
            text: redactedInput.text,
            toolName: toolUse.name,
            toolUseId: toolUse.id,
            ...(redactedCommand ? { command: redactedCommand.text } : {}),
            ...(filePath !== undefined ? { filePath } : {}),
          });

          if (toolUse.result) {
            const truncated = truncateToolOutput(toolUse.result.output ?? '');
            const redactedOutput = redact(truncated);
            redactions += redactedOutput.hits;
            pushEntry({
              ts,
              kind: 'tool_result' as EntryKind,
              text: redactedOutput.text,
              toolName: toolUse.name,
              toolUseId: toolUse.id,
              isError: toolUse.result.status !== 'success',
            });
          }
        } else if ((block as TextBlock).type === 'text' && typeof (block as TextBlock).text === 'string') {
          const r = redact((block as TextBlock).text!);
          redactions += r.hits;
          pushEntry({ ts, kind: 'assistant' as EntryKind, text: r.text });
        }
      }
    }
  }

  return { entries, redactions };
}

import { git } from './git';

const TRAILER_RE = /^Entire-Checkpoint:\s*(\S+)\s*$/m;

function extractCheckpointId(message: string): string | null {
  const m = TRAILER_RE.exec(message);
  return m ? m[1]! : null;
}

const SEP = '\u001e';
const END = '\u001d';

/** Maps checkpoint id -> commit SHAs by scanning commit bodies for an `Entire-Checkpoint:` trailer. */
export async function mapCheckpointCommits(repoDir: string): Promise<Map<string, string[]>> {
  const map = new Map<string, string[]>();

  let out: string;
  try {
    out = await git(repoDir, [
      'log',
      '--exclude=refs/heads/entire/*',
      '--branches',
      '--tags',
      `--format=%H${SEP}%B${END}`,
    ]);
  } catch {
    return map;
  }

  for (const record of out.split(END)) {
    const trimmed = record.replace(/^\n+/, '');
    if (!trimmed.trim()) continue;
    const sepIdx = trimmed.indexOf(SEP);
    if (sepIdx === -1) continue;
    const sha = trimmed.slice(0, sepIdx);
    const body = trimmed.slice(sepIdx + 1);
    const id = extractCheckpointId(body);
    if (!id) continue;
    const list = map.get(id) ?? [];
    list.push(sha);
    map.set(id, list);
  }

  return map;
}

import type { Session } from '@dailies/core';

/** Merges sessions that share an id: keeps the longest transcript, unions checkpoint ids and commits. */
export function mergeSessions(sessions: Session[]): Session[] {
  const byId = new Map<string, Session>();

  for (const session of sessions) {
    const existing = byId.get(session.id);
    if (!existing) {
      byId.set(session.id, session);
      continue;
    }
    const longer = session.entries.length > existing.entries.length ? session : existing;
    byId.set(session.id, {
      ...longer,
      checkpointIds: Array.from(new Set([...existing.checkpointIds, ...session.checkpointIds])),
      commits: Array.from(new Set([...existing.commits, ...session.commits])),
    });
  }

  return Array.from(byId.values());
}

/** Keeps sessions inside [since, until], sorted newest-first, truncated to maxSessions, then returned chronologically. */
export function selectWindow(sessions: Session[], since: string, until: string, maxSessions: number): Session[] {
  const sinceMs = Date.parse(since);
  const untilMs = Date.parse(until);

  const inWindow = sessions.filter((s) => {
    const startedMs = Date.parse(s.startedAt);
    const endedMs = Date.parse(s.endedAt ?? s.startedAt);
    return startedMs <= untilMs && endedMs >= sinceMs;
  });

  const newestFirst = [...inWindow].sort(
    (a, b) => Date.parse(b.endedAt ?? b.startedAt) - Date.parse(a.endedAt ?? a.startedAt),
  );

  return newestFirst.slice(0, maxSessions).sort((a, b) => Date.parse(a.startedAt) - Date.parse(b.startedAt));
}

import type { IngestArtifact, Session } from '@dailies/core';
import { listCheckpointRefs, readCheckpointSessions, type CheckpointRef } from './checkpoints';
import { cloneOrUpdate, getDiff, git } from './git';
import { mapCheckpointCommits } from './trailers';
import { parseTranscript } from './transcript';
import { mergeSessions, selectWindow } from './window';

export { git, cloneOrUpdate, getDiff } from './git';
export { listCheckpointRefs } from './checkpoints';
export type { CheckpointRef } from './checkpoints';
export { parseTranscript } from './transcript';
export { mapCheckpointCommits } from './trailers';

const DEFAULT_MAX_SESSIONS = 12;

export class NoCheckpointsError extends Error {}

async function buildSessionsForCheckpoint(repoDir: string, ref: CheckpointRef, commits: string[]): Promise<{ sessions: Session[]; redactions: number }> {
  const raw = await readCheckpointSessions(repoDir, ref);
  const sessions: Session[] = [];
  let redactions = 0;

  for (const r of raw) {
    const { entries, redactions: hits } = parseTranscript(r.sessionId, r.transcriptJsonl);
    redactions += hits;
    const startedAt = entries[0]?.ts ?? r.createdAt;
    const endedAt = entries.length > 0 ? entries[entries.length - 1]!.ts : null;
    sessions.push({
      id: r.sessionId,
      checkpointIds: [ref.id],
      agent: r.agent,
      model: r.model,
      branch: r.branch,
      startedAt,
      endedAt,
      turnCount: r.turnCount,
      tokens: r.tokens,
      commits,
      filesTouched: r.filesTouched,
      entries,
    });
  }

  return { sessions, redactions };
}

/** Reads a repository's Entire checkpoints into normalized sessions for the given window. */
export async function ingest(opts: {
  repoUrl: string;
  dataDir: string;
  since: string;
  until: string;
  maxSessions?: number;
}): Promise<IngestArtifact> {
  const repoDir = await cloneOrUpdate(opts.repoUrl, opts.dataDir);
  const refs = await listCheckpointRefs(repoDir);
  if (refs.length === 0) throw new NoCheckpointsError(`no checkpoint refs found in ${opts.repoUrl}`);

  const commitMap = await mapCheckpointCommits(repoDir);
  const skipped: { ref: string; reason: string }[] = [];
  let allSessions: Session[] = [];
  let redactions = 0;

  for (const ref of refs) {
    try {
      const commits = commitMap.get(ref.id) ?? [];
      const built = await buildSessionsForCheckpoint(repoDir, ref, commits);
      allSessions = allSessions.concat(built.sessions);
      redactions += built.redactions;
    } catch (err) {
      skipped.push({ ref: ref.treeish, reason: err instanceof Error ? err.message : String(err) });
    }
  }

  const merged = mergeSessions(allSessions);
  const windowed = selectWindow(merged, opts.since, opts.until, opts.maxSessions ?? DEFAULT_MAX_SESSIONS);

  const commitShas = Array.from(new Set(windowed.flatMap((s) => s.commits)));
  const diffs: Record<string, string> = {};
  for (const sha of commitShas) {
    const fileDiffs = await getDiff(repoDir, sha);
    for (const [path, patch] of Object.entries(fileDiffs)) diffs[`${sha}:${path}`] = patch;
  }

  const headSha = await git(repoDir, ['rev-parse', 'HEAD']).then((s) => s.trim()).catch(() => '');

  return {
    repo: { url: opts.repoUrl, dir: repoDir, headSha },
    sessions: windowed,
    diffs,
    skipped,
    enrichments: {},
    redactions,
  };
}

